{"connection_id": "BC-9fc2e286d014bb60c362", "ref": "WLC:Ezek.34.16", "target": "sec14", "tradition": "tevrat", "kind": "motif", "basis": "The lost and strayed are brought back", "note": "God seeks the lost and brings back the strayed, a direct reversal of the commentary's animal that does not know its owner or route home."}
{"connection_id": "BC-b4cf775814b29306dc97", "ref": "WLC:Ezek.34.16", "target": "sec14", "tradition": "tevrat", "kind": "motif", "basis": "seek lost, bring back strayed, bind injured", "note": "The divine shepherd's actions reverse loss, falling, and weakness in the terms developed across the commentary's way and herd images."}
{"connection_id": "BC-1f65f9edb4fbce73198d", "ref": "WLC:Ezek.8.16", "target": "sec14", "tradition": "tevrat", "kind": "motif", "basis": "people worship the sun toward the east", "note": "Ezekiel supplies a concrete scene of sun worship, the precise failure the commentary describes when rising things are treated as Rabb."}
{"connection_id": "BC-10445f0ae2a96de6f9fc", "ref": "WLC:Ezek.9.4", "target": "sec14", "tradition": "tevrat", "kind": "motif", "basis": "a mark set on foreheads before punishment", "note": "Ezekiel joins a distinguishing mark on faces with the approach of judgment, closely meeting the commentary's sign, face, and wrath cluster."}
{"connection_id": "BC-1635bb37d2da23d2f261", "ref": "WLC:Gen.1.14", "target": "sec14", "tradition": "tevrat", "kind": "motif", "basis": "luminaries for signs and seasons", "note": "Genesis calls the heavenly lights signs rather than gods, directly serving the commentary's distinction between a sign and what it signifies."}
{"connection_id": "BC-27c63840dc5a7100e709", "ref": "WLC:Gen.14.19", "target": "sec14", "tradition": "tevrat", "kind": "paralel", "basis": "God Most High is creator of heaven and earth", "note": "Melchizedek blesses Abram by God Most High, maker of heaven and earth, giving concrete language for the commentary's Lord of all worlds."}
{"connection_id": "BC-c049837e0e0c94e2d211", "ref": "WLC:Gen.14.20", "target": "sec14", "tradition": "tevrat", "kind": "paralel", "basis": "Abram blesses the Most High", "note": "Abram blesses God Most High after rescue, meeting the Fatiha's praise of the Lord in a scene where God's help is named."}
{"connection_id": "BC-be76f9478a8d59dce8fb", "ref": "WLC:Gen.14.22", "target": "sec14", "tradition": "tevrat", "kind": "paralel", "basis": "Abram identifies YHWH as creator of heaven and earth", "note": "Abram calls YHWH God Most High and maker of heaven and earth, a direct creator-and-owner claim in his own speech."}
{"connection_id": "BC-d06c7b62b7b09967d0bd", "ref": "WLC:Gen.15.5", "target": "sec14", "tradition": "tevrat", "kind": "karsi_anlati", "basis": "Stars mark a promise, not a deity", "note": "God brings Abram outside to count the stars as a sign of his descendants; unlike the commentary's astral worshippers, the stars here point beyond themselves to the promise-giver."}
{"connection_id": "BC-cf693aee8cd05123e273", "ref": "WLC:Gen.15.5", "target": "sec14", "tradition": "tevrat", "kind": "karsi_anlati", "basis": "Abraham looks at counted stars as promised descendants", "note": "Genesis gives Abraham's star-gazing a covenantal meaning rather than a test of a celestial lord, a meaningful alternative to the commentary's night scene."}
{"connection_id": "BC-06f5ca6cea34dc12e4f4", "ref": "WLC:Gen.18.25", "target": "sec14", "tradition": "tevrat", "kind": "motif", "basis": "Judge of all the earth does justice", "note": "Abraham's appeal to the Judge of all the earth gives a biblical analogue to Rabb al-alamin and the day when justice is rendered."}
{"connection_id": "BC-ba305de45f962f49deac", "ref": "WLC:Gen.18.27", "target": "sec14", "tradition": "tevrat", "kind": "motif", "basis": "I am dust and ashes before the Lord", "note": "Abraham's self-description before judgment supplies a concrete biblical face-to-dust counterpart to the commentary's humiliated, fallen side of the day."}
{"connection_id": "BC-6a5bfbfdd7beaa179cbb", "ref": "WLC:Gen.18.4", "target": "sec14", "tradition": "tevrat", "kind": "motif", "basis": "water for feet and rest under a tree", "note": "Abraham's hospitality gives travelling visitors water and shade, an exact meeting of two images developed in the commentary."}
