{"connection_id": "BC-d2f9d2a4c7c499ba1f89", "ref": "WLC:Ps.103.5", "target": "sec14", "tradition": "tevrat", "kind": "motif", "basis": "Renewed strength and provision", "note": "The psalm says God satisfies the worshipper with good and renews life, a specific image of divine nurture after praise."}
{"connection_id": "BC-7cd02b5bce096cfe3f69", "ref": "WLC:Ps.103.8", "target": "sec14", "tradition": "tevrat", "kind": "motif", "basis": "Compassionate and gracious Lord", "note": "This reprise of YHWH's merciful attributes closely matches the Fatiha's mercy names and the commentary's emphasis on God's completed care."}
