{"connection_id": "BC-f91fb30c2d47422b7b3d", "ref": "WLC:Ps.145.8", "target": "sec14", "tradition": "tevrat", "kind": "motif", "basis": "The Lord is gracious, compassionate, and slow to anger", "note": "This praise formula names the same divine qualities as the Fatiha's mercy names and places them within a hymn of praise."}
{"connection_id": "BC-3fa033e81339deb52d39", "ref": "WLC:Ps.145.9", "target": "sec14", "tradition": "tevrat", "kind": "motif", "basis": "The Lord's compassion extends to all he made", "note": "God's compassion reaches all his works, concretely joining mercy to the commentary's Lord of all worlds."}

